    \overrightarrow{PP_B} = \frac{1}{2} \left( \frac{s(PCA') - s(PCB')}{\sin \theta_B} \right) 
    \overrightarrow{PP_C} = \frac{1}{2} \left( \frac{s(PAB') - s(PAC')}{\sin \theta_C} \right)
